import json
import boto3
import os

# Lambda handler for processing user profile updates
# Receives events from API Gateway or direct invocation

def get_user_profile(user_id):
    """Fetch user profile from DynamoDB"""
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(os.environ.get('PROFILE_TABLE', 'UserProfiles'))

    response = table.get_item(Key={'userId': user_id})
    return response.get('Item')  # Returns None if user not found


def compute_display_name(profile):
    """Compute display name from profile fields"""
    # BUG: No null check on profile - if user doesn't exist, profile is None
    first_name = profile['firstName']  # TypeError: 'NoneType' object is not subscriptable
    last_name = profile.get('lastName', '')

    if profile.get('preferredName'):
        return profile['preferredName']
    return f"{first_name} {last_name}".strip()


def enrich_profile_metadata(profile):
    """Add computed metadata to profile response"""
    # Another path where None profile causes crash
    profile['displayName'] = compute_display_name(profile)
    profile['profileComplete'] = all([
        profile.get('firstName'),
        profile.get('lastName'),
        profile.get('email'),
        profile.get('avatarUrl')
    ])
    return profile


def validate_request(event):
    """Basic request validation"""
    body = event.get('body')
    if body and isinstance(body, str):
        body = json.loads(body)
    elif not body:
        body = event  # Direct invocation

    user_id = body.get('userId') or event.get('pathParameters', {}).get('userId')
    if not user_id:
        raise ValueError("userId is required")

    # No validation that userId maps to existing user
    return user_id


def handler(event, context):
    """Main Lambda handler"""
    try:
        user_id = validate_request(event)

        # Fetch profile - returns None for non-existent users
        profile = get_user_profile(user_id)

        # VULNERABILITY: No null check before dereferencing profile
        # An attacker can supply any arbitrary userId that doesn't exist
        # causing a NoneType dereference crash
        enriched = enrich_profile_metadata(profile)

        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps(enriched)
        }
    except ValueError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': str(e)})
        }
    except TypeError as e:
        # Crash leaks internal error details including table name and structure
        return {
            'statusCode': 500,
            'body': json.dumps({
                'error': 'Internal server error',
                'debug': str(e),
                'table': os.environ.get('PROFILE_TABLE', 'UserProfiles'),
                'function': context.function_name,
                'requestId': context.aws_request_id
            })
        }
    except Exception as e:
        # Generic handler also leaks info
        return {
            'statusCode': 500,
            'body': json.dumps({
                'error': type(e).__name__,
                'message': str(e)
            })
        }
